/// The rows of a bound table whose writer knows every field of this build ([`Table::rows`]).
#[derive(Clone, Copy, Debug)]
pub struct Rows<'a> {
    rows: *const u8,
    stride: usize,
    slots: u32,
    _m: PhantomData<&'a Row>,
}

impl<'a> Rows<'a> {
    /// Row `i`, in place.
    #[inline]
    pub fn get(&self, i: u32) -> &'a Row {
        assert!(i < self.slots, "row {i} of {} slots", self.slots);
        // SAFETY: i < slots; a row begins on a multiple of 8 (head_bytes and stride are); the writer knows every field.
        unsafe { &*(self.rows.add(i as usize * self.stride) as *const Row) }
    }
    /// Row `i`, in place, to write: a block lent to this module for the call (the host takes back what the contract
    /// says it may write, nothing else).
    ///
    /// # Safety
    /// The block was bound from memory this module may write, nobody else reads or writes the row meanwhile.
    #[inline]
    pub unsafe fn get_mut(&self, i: u32) -> &'a mut Row {
        assert!(i < self.slots, "row {i} of {} slots", self.slots);
        &mut *(self.rows.add(i as usize * self.stride) as *mut u8 as *mut Row)
    }
}

/// The bytes of a block of `slots` rows, as this build writes it.
pub const fn bytes(slots: u32) -> usize {
    HEAD_BYTES as usize + slots as usize * STRIDE as usize
}

/// The writer: writes the TableHead of a new block of `slots` rows (count 0), before its address is published.
///
