/// `block` is aligned on 8, holds [`bytes`]`(slots)` bytes, and nobody reads it yet.
pub unsafe fn init(block: *mut u8, slots: u32) {
    TableHead::write(block, &SPEC, slots);
}

/// The writer: the head of its block.
